<nav class="nova-breadcrumbs" aria-label="Fil d’Ariane"><ol><?php foreach($items as $i=>$item): ?><li><?php if($i>0): ?><span aria-hidden="true">/</span><?php endif ?><?php if(!empty($item['href']) && $i<count($items)-1): ?><a href="<?= htmlspecialchars(\Astral\TemplateNova\Template::safeUrl((string) $item['href']), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?>"><?= htmlspecialchars((string)($item['label']??''),ENT_QUOTES,'UTF-8') ?></a><?php else: ?><span aria-current="page"><?= htmlspecialchars((string)($item['label']??''),ENT_QUOTES,'UTF-8') ?></span><?php endif ?></li><?php endforeach ?></ol></nav>
